tasks.setup:
const RANK = { None: 0, SignedSmall: 1, Number: 2, Any: 3 };
function classify(v) {
  if (typeof v === 'string') return 'Any';        // strings widen straight to Any
  if (typeof v === 'number' && Number.isInteger(v) && Math.abs(v) < 2 ** 30) return 'SignedSmall';
  if (typeof v === 'number') return 'Number';
  return 'Any';
}
function merge(state, obs) {
  return RANK[obs] > RANK[state] ? obs : state;
}

